CompositorEffect's shader code:
```shader

#version 450

layout(local_size_x = 8, local_size_y = 8, local_size_z = 1) in;
layout(rgba16f, set = 0, binding = 0) uniform image2D color_image;
layout(set = 1, binding = 0) uniform sampler2D depth_texture;
layout(set = 2, binding = 0, std430) restrict buffer Params {
	vec2 resolution;
	mat4 inv_view_matrix;
	mat4 projection_matrix;
	mat4 inv_projection_matrix;
	float outline_width;
vec4 outline_color;
float m_in;
float m_ax;
} params;


	float get_depth(vec2 uv) {
		float depth = texture(depth_texture,uv).r;
		vec3 ndc = vec3(uv*2.0-1.0,depth);
		vec4 view =  params.inv_projection_matrix * vec4(ndc,1.0);
		view.xyz /= view.w;
		return -view.z;
	}

		float calc_depth(vec2 uv, vec2 offset, float pre_depth){
			float d1 = get_depth(uv+offset);
			float d2 = get_depth(uv-offset);
			return max(abs(d1-d2),pre_depth);
		}

		vec3 rgb_to_hsv(vec3 color){
	float r = color.r;
	float g = color.g;
	float b = color.b;

	float max_v = max(max(r,g),b);
	float min_v = min(min(r,g),b);

	float h, s, v;
	v = max_v;
	if (max_v == 0.0){
		s = 0.0;
	}else{
		s = 1.0 - min_v / max_v;
	}

	if (max_v == min_v){
		h = 0.0;
	}
	else if (max_v == r && g>=b){
		h = 60.0*((g-b)/(max_v-min_v));
	}
	else if(max_v == r && g<b){
		h = 60.0*((g-b)/(max_v-min_v))+360.0;
	}
	else if (max_v == g){
		h = 60.0*((b-r)/(max_v-min_v))+120.0;
	}
	else if (max_v == b){
		h = 60.0*((r-g)/(max_v-min_v))+240.0;
	}
	h /= 360.0f;

	return vec3(h,s,v);
}


vec3 hsv_to_rgb(vec3 color){
	float h = color.x * 360.0f;
	float s = color.y;
	float v = color.z;

	float r,g,b;

	if (s==0.0){
		r = g = b = v;
	}
	else{
		h = h / 60.0;
		int i = int(h);
		float c = h - float(i);

		float x = v * (1.0-s);
		float y = v * (1.0 - s*c);
		float z = v * (1.0 - s*(1.0-c));
		switch (i){
			case 0:r=v;g=z;b=x;break;
			case 1:r=y;g=v;b=x;break;
			case 2:r=x;g=v;b=z;break;
			case 3:r=x;g=y;b=v;break;
			case 4:r=z;g=x;b=v;break;
			case 5:r=v;g=x;b=y;break;
		}
	}

	return vec3(r,g,b);
}


void main() {
	ivec2 coords = ivec2(gl_GlobalInvocationID.xy);
	vec2 pix_size = vec2(1.0)/params.resolution;
	vec2 uv = vec2(coords)*pix_size;

	vec4 color = imageLoad(color_image, coords);


		float depth = 0.0;
		depth = calc_depth(uv, vec2(pix_size.x,0.0),depth);
		depth = calc_depth(uv, vec2(0.0,pix_size.y),depth);
		depth = calc_depth(uv, vec2(pix_size.x,pix_size.y),depth);
		depth = calc_depth(uv, vec2(-pix_size.x,pix_size.y),depth);

		vec3 hsv = rgb_to_hsv(color.rgb);
		float steps = 10.0;
		hsv.g = floor(hsv.g * steps) / steps;
		color.rgb = hsv_to_rgb(hsv);
		color = mix(color, params.outline_color, smoothstep(params.m_in,params.m_ax,depth));


	imageStore(color_image, coords, color);
}
```

